/// Modifier functions from modifiers.h with their mod bits, in the order
/// `name` nests them (outermost first).
const MODS: [(&str, u32); 8] = [
    ("LC", 0x01),
    ("LS", 0x02),
    ("LA", 0x04),
    ("LG", 0x08),
    ("RC", 0x10),
    ("RS", 0x20),
    ("RA", 0x40),
    ("RG", 0x80),
];

/// The value of a ZMK key expression: a `KEYS` name, optionally wrapped in
/// modifier functions (`LC(LS(TAB))`), nested to any depth with whitespace
/// tolerated around names and parentheses. `None` for anything else.
pub(super) fn parse(text: &str) -> Option<u32> {
    let text = text.trim();
    if let Some((func, inner)) = text.split_once('(') {
        let inner = inner.strip_suffix(')')?;
        let (_, mod_bits) = MODS.iter().find(|(f, _)| *f == func.trim())?;
        return Some(mod_bits << 24 | parse(inner)?);
    }
    KEYS.iter().find(|(n, _)| *n == text).map(|&(_, v)| v)
}

/// Canonical text for `value`, the inverse of `parse`: the shortest `KEYS`
/// name with exactly that value (first in table order on ties); otherwise the
/// shortest name of the base usage wrapped in one modifier function per set
/// mod bit, in `MODS` order outermost first. `None` if the base usage has no name.
pub(super) fn name(value: u32) -> Option<String> {
    if let Some(name) = shortest(value) {
        return Some(name.to_owned());
    }
    let mut text = shortest(value & 0x00FF_FFFF)?.to_owned();
    for (func, mod_bits) in MODS.iter().rev() {
        if value >> 24 & mod_bits != 0 {
            text = format!("{func}({text})");
        }
    }
    Some(text)
}

fn shortest(value: u32) -> Option<&'static str> {
    KEYS.iter()
        .filter(|&&(_, v)| v == value)
        .map(|&(n, _)| n)
        .min_by_key(|n| n.len())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_names_and_modifier_functions() {
        assert_eq!(parse("A"), Some(0x07_0004));
        assert_eq!(parse("N1"), Some(0x07_001E));
        assert_eq!(parse("LSHFT"), Some(0x07_00E1));
        assert_eq!(parse("LSHIFT"), Some(0x07_00E1));
        assert_eq!(parse("LEFT_SHIFT"), Some(0x07_00E1));
        assert_eq!(parse("C_VOL_UP"), Some(0x0C_00E9));
        assert_eq!(parse("LC(LS(TAB))"), Some(0x0307_002B));
        assert_eq!(parse(" LC( LS (TAB) ) "), Some(0x0307_002B));
        assert_eq!(parse("EXCL"), Some(0x0207_001E));
        assert_eq!(parse("NOPE"), None);
        assert_eq!(parse("XX(A)"), None);
        assert_eq!(parse("LC(A"), None);
    }

    #[test]
    fn names_prefer_shortest_exact_alias() {
        assert_eq!(name(0x07_0004).as_deref(), Some("A"));
        assert_eq!(name(0x0207_001E).as_deref(), Some("EXCL"));
        assert_eq!(name(0x0307_002B).as_deref(), Some("LC(LS(TAB))"));
        assert_eq!(name(0x07_FFFF), None);
    }

    #[test]
    fn every_key_round_trips() {
        for &(n, v) in KEYS {
            assert_eq!(parse(&name(v).unwrap()), Some(v), "{n}");
        }
    }
}
